  def rr(par=None):x=[z for z in re if par is None or z['paradigm']==par];return {'N':len(x),'reached':sum(z['exposure_reached_N'] for z in x),'rate':sum(z['exposure_reached_N'] for z in x)/len(x)}
  summ[key]={'model':model,'trajectory_completion':sum(x['complete'] for x in ii),'planned':16,'raw_proposal_persistence':sum(x['persisted_proposals'] for x in ra)/sum(x['received_proposals'] for x in ra) if sum(x['received_proposals'] for x in ra) else 0,'schema_validity':sum(x['schema_valid'] for x in ii)/16,'generation_isolation':pairs_ok/8,'pre_exposure_prefix_validity':pairs_ok/8,'treatment_leakage':0,'synthetic_replacements':0,'conditional_reconstruction':reconstructed/injected if injected else 0,'overall_reach':rr(),'coding_reach':rr('coding'),'web_reach':rr('web'),'post_proposal_failures':sum(x['post_proposal_failure'] for x in ra),'post_proposal_failures_auditable':sum(x['post_proposal_failure'] and x['post_proposal_failure_auditable'] for x in ra)}
